	digits := 0
	tmp := n
	for tmp > 0 {
		digits++
		tmp /= 10
	}
	// Compute reflection
	result := 0
	power := int64(math.Pow(10, float64(digits-1)))
	for i := 0; i < digits; i++ {
		digit := n % 10
		n /= 10
		result += (9 - digit) * power
		power /= 10
	}
	return result
}

